-- The Bold Italic — crosswords table + RLS + seed (run in Supabase SQL editor)
create table if not exists public.crosswords (
  id bigint generated always as identity primary key,
  slug text unique not null,
  title text not null,
  subtitle text,
  number int,
  puzzle_date date,
  size int not null,
  symmetry boolean default true,
  grid jsonb not null,
  clues jsonb not null,
  published boolean not null default true,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

alter table public.crosswords enable row level security;
drop policy if exists crosswords_read_published on public.crosswords;
create policy crosswords_read_published on public.crosswords for select using (published = true);
drop policy if exists crosswords_admin_all on public.crosswords;
create policy crosswords_admin_all on public.crosswords for all to authenticated using (true) with check (true);

insert into public.crosswords (slug,title,subtitle,number,puzzle_date,size,symmetry,grid,clues,published) values
