on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, number=excluded.number, puzzle_date=excluded.puzzle_date, size=excluded.size, symmetry=excluded.symmetry, grid=excluded.grid, clues=excluded.clues, published=excluded.published, updated_at=now();
